const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location - Mississippi River near Memphis, TN
  const memphis = ee.Geometry.Point([-90.05, 35.15]);
  const roi = memphis.buffer(10000); // 10km buffer around Memphis

  // 2. Date ranges
  const date2014_start = '2014-02-20';
  const date2014_end = '2014-03-05';
  const date2019_start = '2019-02-18';
  const date2019_end = '2019-03-05';

  // 3. Function to calculate water extent using Landsat 8
  function calculateWaterExtent(startDate, endDate, year) {
    let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    const size = collection.size().getInfo();
    console.log(`${year} Images found: ${size}`);

    if (size === 0) {
      return null;
    }

    // Cloud masking function for Landsat 8 Collection 2
    function maskClouds(image) {
      const qa = image.select('QA_PIXEL');
      const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)
        .and(qa.bitwiseAnd(1 << 4).eq(0));
      return image.updateMask(cloudMask);
    }

    // Calculate MNDWI for water detection
    function addWaterIndex(image) {
      const mndwi = image.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');
      return image.addBands(mndwi);
    }

    const processed = collection
      .map(maskClouds)
      .map(addWaterIndex)
      .median();

    // Threshold MNDWI > 0 for water
    const water = processed.select('MNDWI').gt(0);

    // Count water pixels
    const stats = water.reduceRegion({
      reducer: ee.Reducer.sum().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: roi,
      scale: 30,
      maxPixels: 1e9
    });

    const waterCount = stats.get('MNDWI_sum').getInfo();
    const totalCount = stats.get('MNDWI_count').getInfo();

    console.log(`${year} - Water pixels: ${waterCount}, Valid pixels: ${totalCount}`);

    return { waterCount: waterCount, validCount: totalCount };
  }

  // 4. Calculate for both dates
  const result2014 = calculateWaterExtent(date2014_start, date2014_end, '2014');

  if (result2014 === null) {
    console.log("No images found for 2014");
    console.log("<answer>C1</answer>");
    return;
  }

  if (result2014.validCount === 0) {
    console.log("No valid pixels for 2014 after masking");
    console.log("<answer>C2</answer>");
    return;
  }

  const result2019 = calculateWaterExtent(date2019_start, date2019_end, '2019');

  if (result2019 === null) {
    console.log("No images found for 2019");
    console.log("<answer>C1</answer>");
    return;
  }

  if (result2019.validCount === 0) {
    console.log("No valid pixels for 2019 after masking");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Validation and comparison
  if (result2014.waterCount === null || result2019.waterCount === null ||
      isNaN(result2014.waterCount) || isNaN(result2019.waterCount)) {
    console.log("Calculation failed - invalid results");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`\nComparison: 2019 water extent (${result2019.waterCount}) vs 2014 (${result2014.waterCount})`);

  if (result2019.waterCount > result2014.waterCount) {
    console.log("Surface water extent was HIGHER in 2019");
    console.log("<answer>A</answer>");
  } else {
    console.log("Surface water extent was NOT higher in 2019");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
